import random
from math import comb
# 다수결 정확도: n명이 각각 확률 p 로 맞힐 때(이지선다, n 홀수)
def majority_exact(n, p):
    return sum(comb(n, k) * p**k * (1-p)**(n-k) for k in range(n//2 + 1, n+1))
def majority_sim(n, p, rho, trials=200_000, seed=0):
    # rho: 이번 문제에서 모두가 '같은 생각'(복제본)일 확률 — 동조(conformity)의 단순 모형
    rng, ok = random.Random(seed), 0
    for _ in range(trials):
        if rng.random() < rho:
            ok += rng.random() < p                     # 하나가 맞으면 다 맞고, 틀리면 다 틀린다
        else:
            ok += sum(rng.random() < p for _ in range(n)) > n // 2
    return ok / trials
for n in (1, 3, 5, 9):
    print(n, round(majority_exact(n, 0.7), 4), round(majority_exact(n, 0.4), 4))
print("rho=0.5, n=5:", majority_sim(5, 0.7, 0.5))

# Kim et al. 표 2 의 LLM 호출 수 식에 숫자를 넣어 본다
# n: 에이전트 수, k: 에이전트당 단계, d: 토론 라운드, r: 오케스트레이터 라운드, p: 동료 교신 라운드
def calls(n=3, k=10, d=3, r=3, p=2):
    return {"SAS": k, "Independent": n*k + 1, "Decentralized": d*n*k + 1,
            "Centralized": r*n*k + r, "Hybrid": r*n*k + r + p}
def channels(n):                     # 모두가 모두와 말하면 대화 쌍은 n(n-1)/2
    return n * (n - 1) // 2
print(calls())
print({n: channels(n) for n in (2, 4, 10, 100)})

# DyLAN 의 '에이전트 중요도' 역전파를 3명·2단계로 줄인 장난감
# t=2 의 각 에이전트가 t=1 답들에 매긴 영향 점수(행: t=2 에이전트, 열: t=1 의 doctor, lawyer, insurer)
rate = {"doctor":  [0.6, 0.1, 0.3],
        "lawyer":  [0.5, 0.2, 0.3],
        "insurer": [0.2, 0.2, 0.6]}
final_ok = {"doctor": True, "lawyer": True, "insurer": False}   # 다수결 답과 같았나
names = list(rate)
# 마지막 층: 합의에 낀 에이전트가 1/(합의 인원) 씩 몫을 받는다
agree = [n for n in names if final_ok[n]]
imp_t2 = {n: (1 / len(agree) if n in agree else 0.0) for n in names}
# 한 층 뒤로: 내 몫을 내가 매긴 점수 비율대로 앞 단계에 나눠 준다
imp_t1 = {n: 0.0 for n in names}
for succ, share in imp_t2.items():
    for j, prev in enumerate(names):
        imp_t1[prev] += share * rate[succ][j]
total = {n: imp_t1[n] + imp_t2[n] for n in names}
print({n: round(v, 3) for n, v in total.items()})
print("top-2 team:", sorted(total, key=total.get, reverse=True)[:2])

from collections import defaultdict
# MetaGPT 식 메시지 보드: 구조화된 메시지 + 구독(subscribe) — 관심 있는 종류만 깨운다
class Board:
    def __init__(self): self.log, self.subs = [], defaultdict(list)
    def subscribe(self, agent, cause): self.subs[cause].append(agent)
    def publish(self, msg):
        self.log.append(msg)
        targets = set(self.subs[msg["cause_by"]]) | {a for a in AGENTS if a.name == msg["send_to"]}
        for a in targets: a.inbox.append(msg)
class Agent:
    def __init__(self, name): self.name, self.inbox = name, []
AGENTS = [Agent(n) for n in ("PM", "Architect", "Engineer", "QA")]
pm, arch, eng, qa = AGENTS
b = Board()
b.subscribe(arch, "WritePRD"); b.subscribe(eng, "WriteDesign"); b.subscribe(qa, "WriteCode")
b.publish({"content": "PRD: flappy bird", "cause_by": "WritePRD", "sent_from": "PM", "send_to": ""})
b.publish({"content": "design.md", "cause_by": "WriteDesign", "sent_from": "Architect", "send_to": ""})
b.publish({"content": "fix your bug", "cause_by": "Review", "sent_from": "QA", "send_to": "Engineer"})
for a in AGENTS: print(a.name, [m["content"] for m in a.inbox])

# 작업 장부(task ledger): 할 일·소유자·임대 만료를 한곳에 — 멈춘 일은 남이 다시 가져간다
class Ledger:
    def __init__(self, tasks, lease=2.0):
        self.t = {k: {"state": "todo", "owner": None, "until": 0.0} for k in tasks}
        self.lease = lease
    def claim(self, agent, now):
        for k, v in self.t.items():
            expired = v["state"] == "doing" and v["until"] < now   # 주인이 응답 없음 → 회수
            if v["state"] == "todo" or expired:
                v.update(state="doing", owner=agent, until=now + self.lease)
                return k
        return None
    def done(self, agent, k):
        if self.t[k]["owner"] == agent: self.t[k]["state"] = "done"
L = Ledger(["parse", "codegen", "tests"])
print(L.claim("A", now=0), L.claim("B", now=0))   # A: parse, B: codegen
L.done("A", "parse")                               # B 는 멈춰서 끝내지 못한다
print(L.claim("C", now=1))                         # tests
print(L.claim("A", now=3))                         # codegen 임대 만료 → A 가 넘겨받음
print({k: (v["state"], v["owner"]) for k, v in L.t.items()})
